    public void test_fis() throws Exception
    {
        double[][] mems = new double[][]{
                new double[]{10, 20, 30},
                new double[]{-10, -1, 1, 10},
                new double[]{0, 1}
        };

        HashMap<String, double[]> base = new HashMap<>();
        base.put(".0.0.0", new double[]{1, 0, 0});
        base.put(".0.0.1", new double[]{0, 1, 0});

        base.put(".0.1.0", new double[]{0, 1, 0});
        base.put(".0.1.1", new double[]{0, 0, 1});

        base.put(".0.2.0", new double[]{1, 0, 0});
        base.put(".0.2.1", new double[]{0, 1, 0});

        FIS fis = new FIS(mems, base);

        double[] inp = new double[]{10, -10, 0};
        ArrayList<Pair<String, Double>> inf = fis.fuzzificate(inp);
        double[] res = fis.inference(inp, new double[]{0, 0, 0});
        assertEquals(1, inf.size());
        assertEquals(1.0, inf.get(0).second);
        assertEquals(".0.0.0", inf.get(0).first);
        assertTrue(Arrays.equals(res, base.get(".0.0.0")));

        inp = new double[]{10, -10, 1};
        inf = fis.fuzzificate(inp);
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertEquals(1, inf.size());
        assertEquals(1.0, inf.get(0).second);
        assertEquals(".0.0.1", inf.get(0).first);
        assertTrue(Arrays.equals(res, base.get(".0.0.1")));

        inp = new double[]{10, -10, 0.5};
        inf = fis.fuzzificate(inp);
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertEquals(2, inf.size());
        assertEquals(0.5, inf.get(0).second);
        assertEquals(0.5, inf.get(1).second);
        assertTrue(Arrays.equals(res, new double[]{0.5, 0.5, 0.0}));

        inp = new double[]{10, 0, 0};
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.5, 0.5, 0.0}));

        inp = new double[]{10, 0, 1};
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.0, 0.5, 0.5}));

        inp = new double[]{10, 0, 0.5};
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.25, 0.5, 0.25}));

        inp = new double[]{10, 10, 0.5};
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.0, 0.0, 0.0}));

        fis.train(inp, new double[]{1, 0, 0});
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, base.get(".0.3.0")));

        fis.train(inp, new double[]{0, 1, 0});
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.5, 0.5, 0}));

        fis.train(inp, new double[]{0, 1, 0});
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.25, 0.75, 0}));

        inp = new double[]{10, 10, 1.0};
        fis.train(inp, new double[]{0, 0, 1});
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.0, 0.0, 1}));

        inp = new double[]{10, 10, 0.0};
        res = fis.inference(inp, new double[]{0, 0, 0});
        assertTrue(Arrays.equals(res, new double[]{0.25, 0.75, 0}));
    }

    public void test_fuzzy_node() throws Exception
    {
        fuzzyNode fn = new fuzzyNode(new double[]{10, 20, 30, 40});

        double[] m = fn.inference(0.0);
        assertEquals(4, m.length);
        assertEquals(1.0, m[0]);
        assertEquals(0.0, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(10.0);
        assertEquals(1.0, m[0]);
        assertEquals(0.0, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(15.0);
        assertEquals(0.5, m[0]);
        assertEquals(0.5, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(20.0);
        assertEquals(0.0, m[0]);
        assertEquals(1.0, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(25.0);
        assertEquals(0.0, m[0]);
        assertEquals(0.5, m[1]);
        assertEquals(0.5, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(30.0);
        assertEquals(0.0, m[0]);
        assertEquals(0.0, m[1]);
        assertEquals(1.0, m[2]);
        assertEquals(0.0, m[3]);

        m = fn.inference(40.0);
        assertEquals(0.0, m[0]);
        assertEquals(0.0, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(1.0, m[3]);

        m = fn.inference(41.0);
        assertEquals(0.0, m[0]);
        assertEquals(0.0, m[1]);
        assertEquals(0.0, m[2]);
        assertEquals(1.0, m[3]);

        fn = new fuzzyNode(new double[]{10, 20});

        m = fn.inference(0.0);
        assertEquals(2, m.length);
        assertEquals(1.0, m[0]);
        assertEquals(0.0, m[1]);

        m = fn.inference(10.0);
        assertEquals(1.0, m[0]);
        assertEquals(0.0, m[1]);

        m = fn.inference(15.0);
        assertEquals(0.5, m[0]);
        assertEquals(0.5, m[1]);

        m = fn.inference(20.0);
        assertEquals(0.0, m[0]);
        assertEquals(1.0, m[1]);
    }

    public void test_exercise() throws Exception
    {
        Exercise ex = new Exercise();

        int[] pattern = new int[]{Constants.EXERCISE_PHASE_INHALE, Constants.EXERCISE_PHASE_PAUSE, Constants.EXERCISE_PHASE_EXHALE, Constants.EXERCISE_PHASE_HOLD};
        ex.pattern = pattern;
        ex.events.put(0, new int[]{1000, 0, 1000, 0});
        ex.events.put(4, new int[]{2000, 0, 5000, 0});
        ex.events.put(8, new int[]{1000, 100, 55, 33});
        ex.targetRR.put(0, 1000);
        ex.targetRR.put(5, 600);
        ex.targetRR.put(8, 1200);

        ex.Cycles = 10;
        int[] tp = ex.getTypeScheme();
        for (int i = 4; i < tp.length; i++)
            assertEquals(tp[i], pattern[(i - 4) % pattern.length]);

        int[] dur = new int[]
                {
                        2000, 1000, 800, 800,
                        1000, 0, 1000, 0,
                        1000, 0, 1000, 0,
                        1000, 0, 1000, 0,
                        1000, 0, 1000, 0,
                        2000, 0, 5000, 0,
                        2000, 0, 5000, 0,
                        2000, 0, 5000, 0,
                        2000, 0, 5000, 0,
                        1000, 100, 55, 33,
                        1000, 100, 55, 33
                };
        assertTrue(Arrays.equals(ex.getDurationScheme(), dur));

        int[] control = new int[]
                {
                        0, 0, 0, 0,
                        1000, 1000, 1000, 1000,
                        1000, 1000, 1000, 1000,
                        1000, 1000, 1000, 1000,
                        1000, 1000, 1000, 1000,
                        1000, 1000, 1000, 1000,
                        600, 600, 600, 600,
                        600, 600, 600, 600,
                        600, 600, 600, 600,
                        1200, 1200, 1200, 1200,
                        1200, 1200, 1200, 1200
                };
        assertTrue(Arrays.equals(ex.getControlScheme(), control));
    }

